sys_script.script:
(function executeRule(current, previous) {

    try {
        var userSysId = current.getValue('user');
        var fiscalYearSysId = current.getValue('fiscal_year');

        if (!userSysId || !fiscalYearSysId)
            return;

        var participantGR = new GlideRecordSecure('x_ctans_incentnow_participant_assignment');
        participantGR.addQuery('user', userSysId);
        participantGR.addQuery('fiscal_year', fiscalYearSysId);

        if (!current.isNewRecord())
            participantGR.addQuery('sys_id', '!=', current.getUniqueValue());

        participantGR.setLimit(1);
        participantGR.query();

        if (participantGR.next()) {
            gs.addErrorMessage(
                'A Participant Assignment already exists for user "' +
                current.getDisplayValue('user') +
                '" for Fiscal Year "' +
                current.getDisplayValue('fiscal_year') +
                '". Only one Participant Assignment is allowed per User per Fiscal Year.'
            );

            current.setAbortAction(true);
        }

    } catch (e) {
        gs.error(
            '[IncentIQ Participant Assignment] Duplicate validation failed. Record=' +
            current.getUniqueValue() +
            ', Error=' + e.message
        );

        gs.addErrorMessage(
            'Participant Assignment could not be saved because duplicate validation failed.'
        );

        current.setAbortAction(true);
    }

})(current, previous);
